checks.ref:
command:. .gnomish/lib/task-change.sh
review="$reports/review-code.md"
[ -f "$review" ] || { echo "$review is missing - the review-code stage left it there; restore it from git"; exit 1; }
open=$(grep -nE '^- Status: open' "$review" || true)
[ -z "$open" ] || { echo "$open"; echo "these findings are still open - fix or reject each one, see stages/fix-code/instructions.md"; exit 1; }
bad=$(grep -nE '^- Status: ' "$review" | grep -vE '^[0-9]+:- Status: (fixed|rejected \((false-positive|contradicts-spec|harmful|out-of-scope|not-worth-it)\))$' || true)
[ -z "$bad" ] || { echo "$bad"; echo "a status reads 'fixed' or 'rejected (false-positive|contradicts-spec|harmful|out-of-scope|not-worth-it)'"; exit 1; }
findings=$(grep -cE '^### R[0-9]+ — ' "$review" || true)
resolutions=$(grep -cE '^- Resolution: .{20,}' "$review" || true)
[ "$resolutions" = "$findings" ] || { echo "$review has $findings findings but $resolutions '- Resolution:' lines of substance - every finding gets one, right after its Status"; exit 1; }

